].tataur_c = Cena!tataur_c, [Цена(архив)].tarbag_c = Cena!tarbag_c, [Цена(архив)].zab_kam_c = Cena!zab_kam_c, [Цена(архив)].AMUR_c = Cena!amur_c, [Цена(архив)].rai_c = Cena!rai_c, [Цена(архив)].erk_c = Cena!erk_c, [Цена(архив)].URG_c = Cena!urg_c, [Цена(архив)].USHUM_c = Cena!ushum_c, [Цена(архив)].PRIM_c = Cena!prim_c, [Цена(архив)].bikin_c = Cena!bikin_c, [Цена(архив)].razdol_c = Cena!razdol_c, [Цена(архив)].hankai_c = Cena!hankai_c, [Цена(архив)].YAKUT_c = Cena!yakut_c, [Цена(архив)].neru_c = Cena!neru_c, [Цена(архив)].zyryan_c = Cena!zyryan_c, [Цена(архив)].pyak_c = Cena!pyak_c, [Цена(архив)].MAG_c = Cena!mag_c, [Цена(архив)].CHUKOT_c = Cena!chukot_c, [Цена(архив)].anad_c = Cena!anad_c, [Цена(архив)].bering_c = Cena!bering_c, [Цена(архив)].KAMCH_c = Cena!kamch_c, [Цена(архив)].SAH_c = Cena!sah_c, [Цена(архив)].sost = Cena!sost, [Цена(архив)].[group] = Cena!group
